//#region packages/form/src/utils/actionButton.ts
/** table / group-list 行操作的内置文案。空 text 与未配置一样回退到这里，与 addButtonConfig 一致 */
var DEFAULT_ACTION_BUTTON_TEXT = {
	operate: "操作",
	delete: "删除",
	copy: "复制",
	dropSort: "拖动排序",
	moveUp: "上移",
	moveDown: "下移",
	moveTo: "移动至"
};
var actionButtonText = (config, key) => config?.text || DEFAULT_ACTION_BUTTON_TEXT[key];
/** 解析自定义行操作按钮：过滤掉不显示的，并计算禁用状态与点击回调 */
var resolveCustomActionButtons = (mForm, buttons, ctx, formDisabled) => {
	if (!Array.isArray(buttons)) return [];
	return buttons.filter(({ display }) => typeof display === "function" ? display(mForm, ctx) : display ?? true).map((button) => {
		const { disabled } = button;
		return {
			button,
			disabled: Boolean(formDisabled) || Boolean(typeof disabled === "function" ? disabled(mForm, ctx) : disabled),
			onClick: () => button.handler(mForm, ctx)
		};
	});
};
//#endregion
export { DEFAULT_ACTION_BUTTON_TEXT, actionButtonText, resolveCustomActionButtons };
