//#region runtime/tmagic-form/src/mergeFormOptions.ts
/**
* formPlugin.install 会 setConfig 整对象替换。
* 把宿主 `$MAGIC_FORM` 与画布 `formOptions` 浅合并后再装，避免清空 request / flat 等。
*/
var mergeFormInstallOptions = (host, formOptions = {}) => ({
	...host ?? {},
	...formOptions
});
//#endregion
export { mergeFormInstallOptions };
